import csv,collections,statistics as st
r=list(csv.DictReader(open('responses.csv')))
c=collections.defaultdict(list)
for x in r: c[(x['number_set'],x['target'])].append((int(x['trial_index']),int(x['rating'])))
print(len(c), collections.Counter(len(v) for v in c.values()).most_common(5))
# residual vs trial
m={k:st.mean(y for _,y in v) for k,v in c.items()}
b=collections.defaultdict(list)
for k,v in c.items():
  if len(v)>1:
    for t,y in v: b[t//50].append(y-m[k])
for k in sorted(b): print(k,len(b[k]),round(st.mean(b[k]),3))
# order of sets: same order across participants?
print([x['number_set'] for x in r[:3]], [x['trial_index'] for x in r[:3]])
"

